#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        long long modulus() { return 998244353LL; }

        vector<long long> factStack = {1};
        vector<long long> invFactStack = {1};

        long long fact(int n) {
            while ((int)factStack.size() <= n) {
                long long last = factStack.back();
                factStack.push_back(mult(last, (int)factStack.size()));
            }
            return factStack[n];
        }

        long long fInv(int n) {
            int lastIdx = (int)invFactStack.size() - 1;
            if (lastIdx < n) {
                std::vector<long long> invArr(n - lastIdx);
                invArr[0] = inv(fact(n));
                for (int i = 1; i < (int)invArr.size(); i++) {
                    invArr[i] = mult(invArr[i - 1], n - i + 1);
                }
                for (int i = (int)invArr.size() - 1; i >= 0; i--) {
                    invFactStack.push_back(invArr[i]);
                }
            }
            return invFactStack[n];
        }

        long long ncr(int n, int r) {
            if (n < 0 || r < 0 || n < r) return 0;
            return mult(fact(n), mult(fInv(r), fInv(n - r)));
        }

        long long smallInv(int n) {
            return mult(fInv(n), fact(n - 1));
        }

        long long normalize(long long x) {
            long long m = modulus();
            x %= m;
            if (x < 0) x += m;
            return x;
        }

        long long add(long long a, long long b) {
            long long sum = a + b;
            long long m = modulus();
            return sum >= m ? sum - m : sum;
        }

        long long subtract(long long a, long long b) {
            long long res = a - b;
            long long m = modulus();
            return res < 0 ? res + m : res;
        }

        long long mult(long long a, long long b) {
            return (a * b) % modulus();
        }

        long long inv(long long val) {
            long long g = modulus(), x = 0, y = 1;
            for (long long r = val; r != 0; ) {
                long long q = g / r;
                long long temp = g % r;
                g = r;
                r = temp;

                long long t = x - q * y;
                x = y;
                y = t;
            }
            assert(g == 1);
            assert(y == modulus() || y == -modulus());
            return normalize(x);
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;
    mod.fInv(n + m);
    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(mod.mult(p, n - i), mod.smallInv(n + m - i));
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long term = mod.mult(mod.ncr(n, k), mod.mult(numPhases, phaseSize));
        if ((k & 1) == 1) {
            answer = mod.add(answer, term);
        } else {
            answer = mod.subtract(answer, term);
        }
    }

    cout << answer << "\n";

    return 0;
}

